function solve(region, consent) {
  if (region === 'EU') {
    // For EU users, telemetry defaults to disabled unless consent is explicitly true
    return consent === true;
  } else {
    // Outside EU, telemetry defaults to enabled when consent is missing (null), but explicitly false disables it
    if (consent === false) {
      return false;
    }
    // If consent is null or true, default to enabled
    return true;
  }
}
